 "content": "def transform(grid):
    """Recolor full-width/full-height divider lines to 2."""
    h, w = len(grid), len(grid[0])
    divider_colors = set()
    for row in grid:
        if all(v == row[0] for v in row):
            divider_colors.add(row[0])
    for c in range(w):
        v = grid[0][c]
        if all(grid[r][c] == v for r in range(h)):
            divider_colors.add(v)
    # A divider color is recognized by a complete line. Recolor only its
    # complete lines, preserving isolated occurrences elsewhere.
    full_rows = {r for r, row in enumerate(grid)
                 if all(v == row[0] for v in row) and row[0] in divider_colors}
    full_cols = {c for c in range(w)
                 if all(grid[r][c] == grid[0][c] for r in range(h))
                 and grid[0][c] in divider_colors}
    out = [row[:] for row in grid]
    for r in full_rows:
        out[r] = [2] * w
    for c in full_cols:
        for r in range(h):
            out[r][c] = 2
    return out
